// logger, usage: log(this, "");
const log = global.get('logger');

// Stop when the outside temperature is unavailable
if (!isFinite(msg.feedforward.outside_temp)) {
    log(this, "Outside temperature unavailable", "warn");
    node.status({ fill: "red", shape: "ring", text: "No outside temperature" });
    return null;
}

node.status({});
return msg;

// Forecast temperatures from the cached hourly forecast
const ff = msg.feedforward;
const list = msg.forecast.list; // [{ t: ms, temp: °C }]
const HOUR_MS = 3_600_000;
const now = Date.now();

// Temperature at time t, linear between the hourly forecast points
function at(t) {
    if (t <= list[0].t) return list[0].temp;
    for (let i = 1; i < list.length; i++) {
        if (t <= list[i].t) {
            const a = list[i - 1], b = list[i];
            return a.temp + (b.temp - a.temp) * (t - a.t) / (b.t - a.t);
        }
    }
    return list[list.length - 1].temp;
}

// Average temperature over [from, from + hours], sampled every 15 minutes
function average(from, hours) {
    if (!(hours > 0)) return at(from);
    const steps = Math.round(hours * 4);
    let sum = 0;
    for (let i = 0; i < steps; i++) sum += at(from + (i + 0.5) * hours * HOUR_MS / steps);
    return sum / steps;
}

ff.forecast_now = at(now);                                                            // bias correction
ff.forecast_temp = average(now + ff.forecast_lead_time * HOUR_MS, ff.forecast_window); // heating curve
ff.forecast_avg = average(now, ff.simple_forecast_hours);                             // simple schedule

return msg;

// The heating day starts at the start time, before that time the previous day still counts
const [h, m] = String(msg.feedforward.simple_start_time || "00:00").split(":").map(Number);
const start = new Date();
start.setHours(h || 0, m || 0, 0, 0);
if (Date.now() < start.getTime()) start.setDate(start.getDate() - 1);

msg.feedforward.heating_day = start.toISOString();
return msg;

// Status
const ff = msg.feedforward;
const text = ff.heating ? `${ff.water_temp} °C` : "Off for today";
node.status({ fill: ff.heating ? "green" : "grey", shape: "dot", text: `${text} @ ${ff.outside_temp_used} °C (${ff.mode}, ${ff.source}, ${ff.outside_source})` });

return msg;

// Log unhandled exception
const handle = global.get('unhandledException');
if(handle) handle(this);

return msg;
